# 50 questions for healthcare.db
QUESTIONS = [
{"q":"How many patients are currently in the system?","sql":"SELECT COUNT(*) AS patient_count FROM patients;","difficulty":"easy","category":"simple filtering"},
{"q":"List the names of all doctors who work in the Cardiology department.","sql":"SELECT d.first_name, d.last_name FROM doctors d JOIN departments dept ON d.department_id = dept.department_id WHERE dept.department_name = 'Cardiology';","difficulty":"easy","category":"JOIN"},
{"q":"Which patients are from the state of Texas?","sql":"SELECT first_name, last_name, city FROM patients WHERE state = 'TX';","difficulty":"easy","category":"simple filtering"},
{"q":"What is the average number of years of experience among all doctors?","sql":"SELECT ROUND(AVG(years_experience),2) AS avg_experience FROM doctors;","difficulty":"easy","category":"aggregation"},
{"q":"Which doctor handled the highest number of appointments overall?","sql":"SELECT doc.first_name, doc.last_name, COUNT(*) AS appt_count FROM appointments a JOIN doctors doc ON a.doctor_id = doc.doctor_id GROUP BY a.doctor_id ORDER BY appt_count DESC LIMIT 1;","difficulty":"medium","category":"GROUP BY"},
{"q":"How many appointments were cancelled in total?","sql":"SELECT COUNT(*) FROM appointments WHERE status = 'Cancelled';","difficulty":"easy","category":"simple filtering"},
{"q":"What are the top 5 departments by number of appointments scheduled?","sql":"SELECT dept.department_name, COUNT(*) AS appt_count FROM appointments a JOIN departments dept ON a.department_id = dept.department_id GROUP BY dept.department_name ORDER BY appt_count DESC LIMIT 5;","difficulty":"medium","category":"GROUP BY"},
{"q":"Which patients have visited more than three different departments?","sql":"SELECT p.patient_id, p.first_name, p.last_name, COUNT(DISTINCT a.department_id) AS dept_count FROM patients p JOIN appointments a ON p.patient_id = a.patient_id GROUP BY p.patient_id HAVING COUNT(DISTINCT a.department_id) > 3;","difficulty":"hard","category":"HAVING"},
{"q":"List all diagnoses classified as Severe along with the patient's name.","sql":"SELECT p.first_name, p.last_name, diag.diagnosis_name FROM diagnoses diag JOIN appointments a ON diag.appointment_id = a.appointment_id JOIN patients p ON a.patient_id = p.patient_id WHERE diag.severity = 'Severe';","difficulty":"medium","category":"multiple joins"},
{"q":"How many distinct medications have ever been prescribed?","sql":"SELECT COUNT(DISTINCT medication_id) FROM prescriptions;","difficulty":"easy","category":"COUNT DISTINCT"},
{"q":"What is the most commonly prescribed medication?","sql":"SELECT m.medication_name, COUNT(*) AS times_prescribed FROM prescriptions pr JOIN medications m ON pr.medication_id = m.medication_id GROUP BY m.medication_name ORDER BY times_prescribed DESC LIMIT 1;","difficulty":"medium","category":"GROUP BY"},
{"q":"Which doctors have more than 20 years of experience?","sql":"SELECT first_name, last_name, years_experience FROM doctors WHERE years_experience > 20 ORDER BY years_experience DESC;","difficulty":"easy","category":"simple filtering"},
{"q":"How many appointments does each department have per month in 2024?","sql":"SELECT dept.department_name, strftime('%m', a.appointment_date) AS month, COUNT(*) AS appt_count FROM appointments a JOIN departments dept ON a.department_id = dept.department_id WHERE strftime('%Y', a.appointment_date) = '2024' GROUP BY dept.department_name, month ORDER BY dept.department_name, month;","difficulty":"hard","category":"date functions"},
{"q":"Which patients have never had an appointment marked as Completed?","sql":"SELECT p.patient_id, p.first_name, p.last_name FROM patients p WHERE p.patient_id NOT IN (SELECT patient_id FROM appointments WHERE status = 'Completed');","difficulty":"hard","category":"nested queries"},
{"q":"Find doctors whose number of appointments is above the average number of appointments per doctor.","sql":"SELECT doc.first_name, doc.last_name, COUNT(a.appointment_id) AS appt_count FROM doctors doc JOIN appointments a ON doc.doctor_id = a.doctor_id GROUP BY doc.doctor_id HAVING COUNT(a.appointment_id) > (SELECT AVG(cnt) FROM (SELECT COUNT(*) AS cnt FROM appointments GROUP BY doctor_id));","difficulty":"hard","category":"correlated subqueries"},
{"q":"What is the total cost of medications prescribed to each patient?","sql":"SELECT p.patient_id, p.first_name, p.last_name, ROUND(SUM(m.unit_cost),2) AS total_med_cost FROM patients p JOIN appointments a ON p.patient_id = a.patient_id JOIN prescriptions pr ON a.appointment_id = pr.appointment_id JOIN medications m ON pr.medication_id = m.medication_id GROUP BY p.patient_id ORDER BY total_med_cost DESC LIMIT 10;","difficulty":"hard","category":"multiple joins"},
{"q":"How many patients registered in each year?","sql":"SELECT strftime('%Y', registration_date) AS year, COUNT(*) AS num_registered FROM patients GROUP BY year ORDER BY year;","difficulty":"medium","category":"date functions"},
{"q":"Which insurance provider is used by the most patients?","sql":"SELECT insurance_provider, COUNT(*) AS num_patients FROM patients GROUP BY insurance_provider ORDER BY num_patients DESC LIMIT 1;","difficulty":"easy","category":"aggregation"},
{"q":"List appointments that have no diagnosis recorded.","sql":"SELECT a.appointment_id, a.appointment_date FROM appointments a LEFT JOIN diagnoses diag ON a.appointment_id = diag.appointment_id WHERE diag.diagnosis_id IS NULL;","difficulty":"medium","category":"NULL handling"},
{"q":"What is the youngest and oldest patient's age in the system?","sql":"SELECT MIN(birth_date) AS oldest_birth, MAX(birth_date) AS youngest_birth FROM patients;","difficulty":"easy","category":"aggregation"},
{"q":"Which department has the highest average years of doctor experience?","sql":"SELECT dept.department_name, ROUND(AVG(doc.years_experience),2) AS avg_exp FROM doctors doc JOIN departments dept ON doc.department_id = dept.department_id GROUP BY dept.department_name ORDER BY avg_exp DESC LIMIT 1;","difficulty":"medium","category":"GROUP BY"},
{"q":"Show the five most recent appointments along with patient and doctor names.","sql":"SELECT a.appointment_date, p.first_name || ' ' || p.last_name AS patient_name, doc.first_name || ' ' || doc.last_name AS doctor_name FROM appointments a JOIN patients p ON a.patient_id = p.patient_id JOIN doctors doc ON a.doctor_id = doc.doctor_id ORDER BY a.appointment_date DESC LIMIT 5;","difficulty":"medium","category":"ORDER BY"},
{"q":"How many diagnoses of Type 2 Diabetes have been recorded?","sql":"SELECT COUNT(*) FROM diagnoses WHERE diagnosis_name = 'Type 2 Diabetes';","difficulty":"easy","category":"simple filtering"},
{"q":"What percentage of appointments resulted in a no-show?","sql":"SELECT ROUND(100.0 * SUM(CASE WHEN status='No-show' THEN 1 ELSE 0 END) / COUNT(*), 2) AS no_show_pct FROM appointments;","difficulty":"medium","category":"aggregation"},
{"q":"Which doctors have never prescribed any medication?","sql":"SELECT DISTINCT doc.doctor_id, doc.first_name, doc.last_name FROM doctors doc WHERE doc.doctor_id NOT IN (SELECT DISTINCT a.doctor_id FROM appointments a JOIN prescriptions pr ON a.appointment_id = pr.appointment_id);","difficulty":"hard","category":"nested queries"},
{"q":"For each department, what is the cancellation rate of appointments?","sql":"SELECT dept.department_name, ROUND(100.0 * SUM(CASE WHEN a.status='Cancelled' THEN 1 ELSE 0 END)/COUNT(*),2) AS cancel_rate FROM appointments a JOIN departments dept ON a.department_id = dept.department_id GROUP BY dept.department_name ORDER BY cancel_rate DESC;","difficulty":"hard","category":"GROUP BY"},
{"q":"Which patient has had the most appointments with a single doctor?","sql":"SELECT p.first_name, p.last_name, doc.first_name AS doc_first, doc.last_name AS doc_last, COUNT(*) AS visits FROM appointments a JOIN patients p ON a.patient_id=p.patient_id JOIN doctors doc ON a.doctor_id=doc.doctor_id GROUP BY a.patient_id, a.doctor_id ORDER BY visits DESC LIMIT 1;","difficulty":"medium","category":"GROUP BY"},
{"q":"List medications that cost more than $2 per unit.","sql":"SELECT medication_name, unit_cost FROM medications WHERE unit_cost > 2.0 ORDER BY unit_cost DESC;","difficulty":"easy","category":"simple filtering"},
{"q":"How many unique patients has each doctor treated?","sql":"SELECT doc.first_name, doc.last_name, COUNT(DISTINCT a.patient_id) AS unique_patients FROM doctors doc JOIN appointments a ON doc.doctor_id = a.doctor_id GROUP BY doc.doctor_id ORDER BY unique_patients DESC LIMIT 10;","difficulty":"medium","category":"COUNT DISTINCT"},
{"q":"What is the average appointment count per patient?","sql":"SELECT ROUND(AVG(cnt),2) AS avg_appts_per_patient FROM (SELECT patient_id, COUNT(*) AS cnt FROM appointments GROUP BY patient_id);","difficulty":"medium","category":"aggregation"},
{"q":"Which department had the most Severe diagnoses last year?","sql":"SELECT dept.department_name, COUNT(*) AS severe_count FROM diagnoses diag JOIN appointments a ON diag.appointment_id=a.appointment_id JOIN departments dept ON a.department_id=dept.department_id WHERE diag.severity='Severe' AND strftime('%Y', a.appointment_date) = strftime('%Y', 'now', '-1 year') GROUP BY dept.department_name ORDER BY severe_count DESC LIMIT 1;","difficulty":"hard","category":"date functions"},
{"q":"Find patients who share the same insurance provider as patient with ID 1.","sql":"SELECT patient_id, first_name, last_name FROM patients WHERE insurance_provider = (SELECT insurance_provider FROM patients WHERE patient_id = 1) AND patient_id != 1;","difficulty":"medium","category":"nested queries"},
{"q":"What is the median-ish middle appointment count among doctors (using average as approximation), and which doctors exceed it by more than double?","sql":"SELECT doc.first_name, doc.last_name, COUNT(*) AS appt_count FROM appointments a JOIN doctors doc ON a.doctor_id=doc.doctor_id GROUP BY doc.doctor_id HAVING COUNT(*) > 2 * (SELECT AVG(cnt) FROM (SELECT COUNT(*) cnt FROM appointments GROUP BY doctor_id));","difficulty":"hard","category":"correlated subqueries"},
{"q":"How many appointments happened on weekends?","sql":"SELECT COUNT(*) FROM appointments WHERE strftime('%w', appointment_date) IN ('0','6');","difficulty":"medium","category":"date functions"},
{"q":"List the top 3 most expensive medications by unit cost.","sql":"SELECT medication_name, unit_cost FROM medications ORDER BY unit_cost DESC LIMIT 3;","difficulty":"easy","category":"LIMIT"},
{"q":"Which doctors work in a department located above the 5th floor?","sql":"SELECT doc.first_name, doc.last_name, dept.department_name, dept.floor_number FROM doctors doc JOIN departments dept ON doc.department_id = dept.department_id WHERE dept.floor_number > 5;","difficulty":"easy","category":"JOIN"},
{"q":"What is the gender distribution of patients?","sql":"SELECT gender, COUNT(*) AS num_patients FROM patients GROUP BY gender;","difficulty":"easy","category":"GROUP BY"},
{"q":"For each medication category, what is the average unit cost?","sql":"SELECT category, ROUND(AVG(unit_cost),2) AS avg_cost FROM medications GROUP BY category ORDER BY avg_cost DESC;","difficulty":"easy","category":"aggregation"},
{"q":"Which patients have a diagnosis but no prescription for the same appointment?","sql":"SELECT DISTINCT p.first_name, p.last_name, a.appointment_id FROM patients p JOIN appointments a ON p.patient_id=a.patient_id JOIN diagnoses d ON a.appointment_id=d.appointment_id WHERE a.appointment_id NOT IN (SELECT appointment_id FROM prescriptions);","difficulty":"hard","category":"nested queries"},
{"q":"How many doctors head a department?","sql":"SELECT COUNT(DISTINCT head_doctor_id) FROM departments WHERE head_doctor_id IS NOT NULL;","difficulty":"easy","category":"NULL handling"},
{"q":"What is the total number of appointments per year, ordered chronologically?","sql":"SELECT strftime('%Y', appointment_date) AS year, COUNT(*) AS total FROM appointments GROUP BY year ORDER BY year;","difficulty":"medium","category":"date functions"},
{"q":"Which doctor prescribed the widest variety of distinct medications?","sql":"SELECT doc.first_name, doc.last_name, COUNT(DISTINCT pr.medication_id) AS distinct_meds FROM doctors doc JOIN appointments a ON doc.doctor_id=a.doctor_id JOIN prescriptions pr ON a.appointment_id=pr.appointment_id GROUP BY doc.doctor_id ORDER BY distinct_meds DESC LIMIT 1;","difficulty":"hard","category":"COUNT DISTINCT"},
{"q":"Find patients whose GPA-like severity pattern shows only Mild diagnoses (i.e., patients who only ever received Mild severity diagnoses).","sql":"SELECT DISTINCT p.first_name, p.last_name FROM patients p JOIN appointments a ON p.patient_id=a.patient_id JOIN diagnoses d ON a.appointment_id=d.appointment_id WHERE p.patient_id NOT IN (SELECT a2.patient_id FROM appointments a2 JOIN diagnoses d2 ON a2.appointment_id=d2.appointment_id WHERE d2.severity != 'Mild');","difficulty":"hard","category":"correlated subqueries"},
{"q":"What is the busiest day of the week for appointments?","sql":"SELECT CASE strftime('%w', appointment_date) WHEN '0' THEN 'Sunday' WHEN '1' THEN 'Monday' WHEN '2' THEN 'Tuesday' WHEN '3' THEN 'Wednesday' WHEN '4' THEN 'Thursday' WHEN '5' THEN 'Friday' WHEN '6' THEN 'Saturday' END AS day_name, COUNT(*) AS cnt FROM appointments GROUP BY day_name ORDER BY cnt DESC LIMIT 1;","difficulty":"medium","category":"date functions"},
{"q":"List doctors along with the number of departments they've ever been head of (0 or 1).","sql":"SELECT doc.first_name, doc.last_name, (SELECT COUNT(*) FROM departments dept WHERE dept.head_doctor_id = doc.doctor_id) AS is_head FROM doctors doc;","difficulty":"medium","category":"correlated subqueries"},
{"q":"Which three patients have the highest total prescription duration (sum of days across all prescriptions)?","sql":"SELECT p.first_name, p.last_name, SUM(pr.duration_days) AS total_days FROM patients p JOIN appointments a ON p.patient_id=a.patient_id JOIN prescriptions pr ON a.appointment_id=pr.appointment_id GROUP BY p.patient_id ORDER BY total_days DESC LIMIT 3;","difficulty":"medium","category":"multiple joins"},
{"q":"How many appointments are missing a recorded reason?","sql":"SELECT COUNT(*) FROM appointments WHERE reason IS NULL;","difficulty":"easy","category":"NULL handling"},
{"q":"What is the average patient age by state?","sql":"SELECT state, ROUND(AVG((julianday('now') - julianday(birth_date))/365.25),1) AS avg_age FROM patients GROUP BY state ORDER BY avg_age DESC;","difficulty":"medium","category":"date functions"},
{"q":"Which specialty has treated the most unique patients?","sql":"SELECT doc.specialty, COUNT(DISTINCT a.patient_id) AS unique_patients FROM doctors doc JOIN appointments a ON doc.doctor_id = a.doctor_id GROUP BY doc.specialty ORDER BY unique_patients DESC LIMIT 1;","difficulty":"medium","category":"COUNT DISTINCT"},
{"q":"Find the second most common diagnosis overall.","sql":"SELECT diagnosis_name, COUNT(*) AS cnt FROM diagnoses GROUP BY diagnosis_name ORDER BY cnt DESC LIMIT 1 OFFSET 1;","difficulty":"medium","category":"LIMIT"},
{"q":"List patients registered before 2020 who still have appointments scheduled in the future.","sql":"SELECT DISTINCT p.first_name, p.last_name FROM patients p JOIN appointments a ON p.patient_id=a.patient_id WHERE p.registration_date < '2020-01-01' AND a.appointment_date > date('now');","difficulty":"hard","category":"date functions"},
]
